[SRSReportDataSetAttribute(tableStr(ConDemoDpTestTmp))]
public ConDemoDpTestTmp getDemoDpTestTmp()
{
    ConDemoDpTestTmp result;

    select * from result;
    return result;
}

public void processReport()
{
    ConDemoNoteHeader source;
    ConDemoDpTestTmp tmp;

    while select source
    {
        tmp.clear();
        tmp.NoteId  = source.NoteId;
        tmp.Subject = source.Subject;
        tmp.insert();
    }
}
